const items = $input.all();
const results = [];
for (const item of items) {
  const cvLink = item.json['Google Docs CV Link'] || item.json['google_docs_cv_link'] || '';
  const jobDescription = item.json['Job Description'] || item.json['job_description'] || '';
  let documentId = '';
  const match = cvLink.match(/\/document\/d\/([a-zA-Z0-9_-]+)/);
  if (match) { documentId = match[1]; }
  else if (/^[a-zA-Z0-9_-]{20,}$/.test(cvLink.trim())) { documentId = cvLink.trim(); }
  if (!documentId) throw new Error('Invalid Google Docs link.');
  if (!jobDescription || jobDescription.trim().length < 20) throw new Error('Job description too short.');
  results.push({ json: { documentId, jobDescription: jobDescription.trim(), originalLink: cvLink } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const doc = item.json;
  let cvText = '';
  if (doc.body && doc.body.content) {
    for (const element of doc.body.content) {
      if (element.paragraph && element.paragraph.elements) {
        for (const el of element.paragraph.elements) {
          if (el.textRun && el.textRun.content) cvText += el.textRun.content;
        }
      }
      if (element.table) {
        for (const row of (element.table.tableRows || [])) {
          for (const cell of (row.tableCells || [])) {
            if (cell.content) {
              for (const ce of cell.content) {
                if (ce.paragraph && ce.paragraph.elements) {
                  for (const el of ce.paragraph.elements) {
                    if (el.textRun && el.textRun.content) cvText += el.textRun.content;
                  }
                }
              }
            }
            cvText += '\t';
          }
          cvText += '\n';
        }
      }
    }
  }
  if (!cvText && doc.text) cvText = doc.text;
  if (!cvText && doc.content) cvText = typeof doc.content === 'string' ? doc.content : JSON.stringify(doc.content);
  let prevData = {};
  try { prevData = $('Extract Doc ID').first().json; } catch(e) {}
  results.push({ json: { cvText: cvText.trim(), documentId: prevData.documentId || '', jobDescription: prevData.jobDescription || '', originalLink: prevData.originalLink || '', docTitle: doc.title || 'Untitled CV' } });
}
return results;

const items = $input.all();
const results = [];
const SYSTEM_PROMPT = `You are an expert ATS keyword analyst. Analyze the job description and the candidate's CV, then extract the most impactful keywords to inject.

Think step by step:
1. Read the JD carefully. Identify MUST-HAVE skills, tools, methodologies, and domain terms.
2. Read the CV. Identify which JD keywords are MISSING or could replace weaker synonyms.
3. Rank keywords by ATS impact: exact JD matches score highest.
4. For each keyword, identify WHICH CV bullet point it fits most naturally into.

Return ONLY a JSON object with this structure (no markdown, no explanation):
{"keywords": [{"keyword": "exact term from JD", "priority": "high|medium", "target_bullet": "first 10 words of the CV bullet where this fits best", "reason": "brief reason"}]}

Rules:
- Extract 10-20 keywords max
- Only keywords that genuinely relate to the candidate's existing experience
- Never suggest keywords that would require fabricating new experience
- Include both technical skills and soft skills/methodologies from JD
- Prefer exact JD phrasing over synonyms`;

for (const item of items) {
  const cvText = item.json.cvText || '';
  const jd = item.json.jobDescription || '';
  const userMsg = 'CV:\n' + cvText + '\n\nJOB DESCRIPTION:\n' + jd;
  const payload = { model: 'qwen3-32b', temperature: 0.6, max_tokens: 8000, messages: [{ role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: userMsg }] };
  results.push({ json: { ...item.json, keywordPayload: JSON.stringify(payload) } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  let keywords = [];
  let error = '';
  if (data.error || data.errorMessage || data.statusCode === 429 || data.statusCode >= 400) {
    error = data.error || data.errorMessage || 'HTTP ' + data.statusCode;
  }
  try {
    if (!error && data.choices && data.choices.length > 0) {
      let content = data.choices[0].message.content || '';
      content = content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
      content = content.replace(/^```[a-z]*\n?/gm, '').replace(/```$/gm, '').trim();
      const parsed = JSON.parse(content);
      keywords = parsed.keywords || parsed;
      if (!Array.isArray(keywords)) throw new Error('Not an array');
    }
  } catch (e) { error = 'Failed to parse keyword response: ' + e.message; }
  if (!error && keywords.length === 0) error = 'No keywords extracted';
  let prevData = {};
  try { prevData = $('Extract CV Text').first().json; } catch(e) {}
  results.push({ json: { keywords, error, cvText: prevData.cvText || '', documentId: prevData.documentId || '', jobDescription: prevData.jobDescription || '', originalLink: prevData.originalLink || '', docTitle: prevData.docTitle || '' } });
}
return results;

const items = $input.all();
const results = [];
const SYSTEM_PROMPT = `You are an ATS resume editor. You receive a CV, a list of extracted keywords with target bullets, and must produce find-and-replace pairs.

RULES:
1. ONLY modify experience/work bullet points and skills lines. Do NOT touch: name, contact info, education, certifications, dates, company names, job titles, section headers.
2. For each replacement: {"find": "exact original text from CV", "replace": "enhanced text with keywords woven in"}
3. The "find" value MUST be an EXACT character-for-character substring from the CV. If wrong, the replacement silently fails.
4. Weave in 1-3 keywords per bullet NATURALLY — no awkward stuffing.
5. Keep bullet length similar. Do not bloat.
6. Replace generic synonyms with exact JD terminology.
7. Do NOT fabricate metrics, tools, or experiences.
8. Produce 8-15 replacements max.
9. You MAY include 1-2 skill line replacements to add related skills.
10. Return ONLY a valid JSON array. No markdown, no explanation, no code fences.

Example: [{"find":"Built REST APIs for internal tools","replace":"Built scalable REST APIs and microservices for internal tools using Node.js"}]`;

for (const item of items) {
  const cvText = item.json.cvText || '';
  const keywords = item.json.keywords || [];
  const kwSummary = keywords.map(k => k.keyword + ' (priority: ' + k.priority + ', target: ' + (k.target_bullet || 'any') + ')').join('\n');
  const userMsg = 'CV:\n' + cvText + '\n\nKEYWORDS TO INJECT:\n' + kwSummary;
  const payload = { model: 'llama-3.3-70b-versatile', temperature: 0.3, max_tokens: 4000, messages: [{ role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: userMsg }] };
  results.push({ json: { ...item.json, aiPayload: JSON.stringify(payload) } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  let replacements = [];
  let error = '';
  if (data.error || data.errorMessage || data.statusCode === 429 || data.statusCode >= 400) {
    error = data.error || data.errorMessage || 'HTTP ' + data.statusCode;
  }
  try {
    if (!error && data.choices && data.choices.length > 0) {
      let content = data.choices[0].message.content || '';
      content = content.replace(/^```[a-z]*\n?/gm, '').replace(/```$/gm, '').trim();
      replacements = JSON.parse(content);
      if (!Array.isArray(replacements)) throw new Error('Not an array');
      replacements = replacements.filter(r => r.find && r.replace && r.find.trim().length > 5 && r.find !== r.replace);
      if (replacements.length === 0) error = 'AI returned no valid replacements';
    }
  } catch (e) { error = 'Failed to parse AI response: ' + e.message; }
  if (!error && replacements.length === 0) error = 'AI returned empty response';
  let prevData = {};
  try { prevData = $('Parse Keywords').first().json; } catch(e) {}
  results.push({ json: { replacements, error, keywords: prevData.keywords || [], documentId: prevData.documentId || '', jobDescription: prevData.jobDescription || '', originalLink: prevData.originalLink || '', docTitle: prevData.docTitle || 'Untitled CV' } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const copiedDocId = item.json.id || '';
  if (!copiedDocId) throw new Error('Failed to copy document — no ID returned');
  let prevData = {};
  try { prevData = $('Parse AI Response').first().json; } catch(e) {}
  const replacements = prevData.replacements || [];
  const requests = replacements.map(r => ({
    replaceAllText: {
      containsText: { text: r.find, matchCase: true },
      replaceText: r.replace
    }
  }));
  const requestBody = JSON.stringify({ requests });
  results.push({ json: { copiedDocId, requestBody, replacementCount: requests.length } });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  let prevData = {};
  try { prevData = $('Parse AI Response').first().json; } catch(e) {}
  let buildData = {};
  try { buildData = $('Build Replace Requests').first().json; } catch(e) {}
  const replacements = prevData.replacements || [];
  const docId = buildData.copiedDocId || '';
  const docUrl = docId ? 'https://docs.google.com/document/d/' + docId + '/edit' : 'URL unavailable';
  const changes = replacements.map((r, i) => ({
    change_number: i + 1,
    original: r.find,
    updated: r.replace,
    keywords_added: r.replace.split(/[\s,;]+/).filter(w => !r.find.toLowerCase().includes(w.toLowerCase()) && w.length > 2).join(', ')
  }));
  results.push({
    json: {
      status: 'success',
      message: '✅ Optimized CV created!',
      total_changes: changes.length,
      documentUrl: docUrl,
      documentId: docId,
      changes: changes
    }
  });
}
return results;
